        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function renderField({ id, label, type, name, placeholder, required, autocomplete, helperText, errorText, invalid, inputMode }) {
      return `
        <div class="form-field ${invalid ? "field-invalid" : ""}">
          <label for="${id}">
            ${escapeHtml(label)}${required ? ' <span class="required">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            placeholder="${escapeHtml(placeholder)}"
            ${required ? "required" : ""}
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            ${inputMode ? `inputmode="${inputMode}"` : ""}
            aria-invalid="${invalid ? "true" : "false"}"
            aria-describedby="${helperText || errorText ? `${id}-help${errorText ? ` ${id}-error` : ""}` : ""}"
          />
          ${helperText ? `<p id="${id}-help" class="helper-text">${escapeHtml(helperText)}</p>` : ""}
          ${invalid && errorText ? `<p id="${id}-error" class="error-text">${escapeHtml(errorText)}</p>` : ""}
        </div>
      `;
    }

    function SupportContactForm(state) {
      const errors = state.errors || {};
      return `
        <section class="card" aria-labelledby="support-title">
          <div class="card-header">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">Contact our team</h1>
            <p class="lede">
              Send us your details and we’ll connect you with the right support specialist.
            </p>
          </div>
          <div class="card-body">
            <p class="status" role="status" aria-live="polite">${escapeHtml(state.statusMessage || "")}</p>
            <form novalidate>
              ${renderField({
