                label: "Full name",
                type: "text",
                name: "fullName",
                placeholder: "Jane Doe",
                required: true,
                autocomplete: "name",
                errorText: errors.fullName,
                invalid: Boolean(errors.fullName)
              })}
              ${renderField({
                id: "email-address",
                label: "Email address",
                type: "email",
                name: "email",
                placeholder: "jane@example.com",
                required: true,
                autocomplete: "email",
