              <div class="actions">
                <button type="submit">Submit</button>
              </div>
            </form>
          </div>
        </section>
      `;
    }

    function validate(formData) {
      const errors = {};
      const fullName = formData.get("fullName").trim();
      const email = formData.get("email").trim();

      if (!fullName) {
        errors.fullName = "Full name is required.";
