          />
          ${helperText ? `<p id="${id}-help" class="helper-text">${escapeHtml(helperText)}</p>` : ""}
          ${invalid && errorText ? `<p id="${id}-error" class="error-text">${escapeHtml(errorText)}</p>` : ""}
        </div>
      `;
    }

    function SupportContactForm(state) {
      const errors = state.errors || {};
      return `
        <section class="card" aria-labelledby="support-title">
          <div class="card-header">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">Contact our team</h1>
