          ${helperText ? `<p id="${id}-help" class="helper-text">${escapeHtml(helperText)}</p>` : ""}
          ${invalid && errorText ? `<p id="${id}-error" class="error-text">${escapeHtml(errorText)}</p>` : ""}
        </div>
      `;
    }

