                id: "full-name",
                label: "Full name",
                type: "text",
                name: "fullName",
                placeholder: "Jane Doe",
                required: true,
                autocomplete: "name",
                errorText: errors.fullName,
                invalid: Boolean(errors.fullName)
              })}
